(function(){'use strict';
const hub=document.getElementById('g-session-hub'),W=window.NavigatorWorkflowSession,T=window.NavigatorTimelineUI;if(!hub||!W||!T)return;
hub.innerHTML=`<div class="session-heading"><div><span class="g-label">Your private workspace</span><h2>Save and resume your work.</h2><p>One local file keeps your recorded choices, document progress and timeline together.</p></div><div class="g-button-row"><button class="g-btn" id="session-save" type="button">Save recovery file</button><button class="g-btn secondary" id="session-restore-open" type="button">Resume from a file</button></div></div><p id="session-save-status" class="g-mini" role="status">This tab has no automatic save. Keep your recovery file in an institution-approved secure location.</p><details id="session-onboarding"><summary>New here? Your first three steps</summary><ol class="session-onboarding"><li><strong>Keep identities outside Navigator.</strong> Use codes and retain the official signed records in your institution’s secure system.</li><li><strong>Work on the current step.</strong> Choose the actual situation, prepare the relevant draft and record verified dates when asked. The Committee reviews and authorises every action.</li><li><strong>Save before leaving.</strong> Download a recovery file, then use Resume from a file next time. It contains your recorded choices and timeline, not downloaded Word files or unrecorded form text.</li></ol><p>Detailed legal guidance stays collapsed beside each step. Learning scenarios are synthetic examples; use Start from the beginning for your own procedural session.</p><button class="g-btn secondary" id="session-ready" type="button">Ready — go to current step</button></details><section id="session-restore-panel" class="session-restore" hidden><h3>Restore a local recovery file</h3><label for="session-file">Choose a Navigator JSON export</label><input id="session-file" type="file" accept=".json,application/json"><p>Files are read in this tab, never uploaded. Recovery files are readable JSON; protect them like internal procedural records. Imported history is untrusted and must be checked against source records.</p><p id="session-restore-preview" role="status"></p><button id="session-restore-confirm" class="g-btn" type="button" hidden>Replace this tab with the reviewed file</button><button id="session-restore-cancel" class="g-btn secondary" type="button">Cancel restore</button></section><p id="session-error" class="g-alert" role="alert" hidden></p>`;
const toolbar=document.querySelector('.g-toolbar');if(toolbar)document.querySelector('.g-shell').append(toolbar);const note=document.querySelector('.g-session-note');if(note)note.textContent='Use participant codes; keep original case records with your institution.';const $=id=>document.getElementById(id);let saved='',lastSaved='',pending=null,unrecorded=false,submitting='';const dirtyForms=new Set();
function snapshot(){return{format:'posh-navigator-session',schemaVersion:1,workflow:W.snapshot(),timeline:T.snapshot()};}
let baseline=JSON.stringify(snapshot());
function dirty(){return unrecorded||JSON.stringify(snapshot())!==(saved||baseline);}
function status(){const changed=dirty();$('session-save-status').textContent=(lastSaved?'Recovery download started at '+lastSaved+'. ':'')+(changed?'Changes in this tab are not in your last recovery file. Save before leaving.':'This tab has no automatic save. Keep your recovery file securely on your device.')+(unrecorded?' Unrecorded form text is not included; submit the relevant record before saving.':'');}
function save(){const value=snapshot(),url=URL.createObjectURL(new Blob([JSON.stringify({...value,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='POSH-Navigator-Recovery-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);saved=JSON.stringify(value);lastSaved=new Date().toLocaleTimeString('en-IN');status();}
$('session-save').onclick=save;window.NavigatorSessionExperience={save,hasUnsavedChanges:dirty};
$('session-restore-open').onclick=()=>{$('session-restore-panel').hidden=false;$('session-file').focus();};
$('session-ready').onclick=()=>{$('session-onboarding').open=false;const body=document.getElementById('g-body');body.setAttribute('tabindex','-1');body.focus();body.scrollIntoView({block:'start'});};
function cancel(){pending=null;$('session-file').value='';$('session-restore-confirm').hidden=true;$('session-restore-panel').hidden=true;$('session-restore-preview').textContent='';}
$('session-restore-cancel').onclick=cancel;
$('session-file').onchange=async e=>{pending=null;$('session-restore-confirm').hidden=true;$('session-error').hidden=true;try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Choose a file smaller than 2 MB.');const data=JSON.parse(await file.text());let workflow=data.workflow,timeline=data.timeline,legacy=false;if(data.version===1&&Array.isArray(data.audit)){legacy=true;timeline=data;workflow={answers:{},decisions:{},documentTrail:[],status:'',chosenAction:'',checked:[],workSteps:[],uncertainSteps:[],followupDetail:'',lastKey:'',scenario:'manual'};}else if(data.format!=='posh-navigator-session'||data.schemaVersion!==1)throw Error('Unsupported recovery format.');const applyWorkflow=W.prepare(workflow),applyTimeline=T.prepareRestore(timeline);pending=()=>{applyWorkflow();applyTimeline();};$('session-restore-preview').textContent=(legacy?'Timeline-only export: questions restart at P01. ':'Full session: '+Object.keys(workflow.answers).length+' recorded answers and '+workflow.documentTrail.length+' document steps. ')+timeline.events.length+' timeline events. Restoring replaces this tab; save its current work first. Dates and decisions remain unverified imported records.';$('session-restore-confirm').hidden=false;}catch(e){$('session-error').hidden=false;$('session-error').className='g-alert';$('session-error').textContent='Restore was not applied: '+e.message;$('session-restore-preview').textContent='Your current session is unchanged.';}};
$('session-restore-confirm').onclick=()=>{if(!pending)return;pending();priorScenario=document.getElementById('g-scenario').value;saved='';baseline='';unrecorded=false;dirtyForms.clear();cancel();$('session-error').hidden=false;$('session-error').className='g-soft';$('session-error').textContent='Restored locally from an untrusted file. Verify all choices, dates and history against institutional records, then save a fresh recovery file.';status();};
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});
let priorScenario=document.getElementById('g-scenario').value;document.addEventListener('change',e=>{if(e.target.id!=='g-scenario')return;if(dirty()&&!confirm('Changing the scenario replaces workflow choices. Save a recovery file first if needed. Timeline dates remain unchanged. Continue?')){e.target.value=priorScenario;e.stopImmediatePropagation();return;}priorScenario=e.target.value;},true);document.addEventListener('click',e=>{if(!['g-restart','g-reset-inline'].includes(e.target.id)||!dirty())return;if(!confirm('Starting over replaces workflow choices. Save a recovery file first if needed. Timeline dates remain unchanged. Continue?')){e.preventDefault();e.stopImmediatePropagation();}},true);
document.getElementById('g-timeline').addEventListener('input',e=>{if(e.target.form)dirtyForms.add(e.target.form.id);unrecorded=dirtyForms.size>0;status();});document.getElementById('g-timeline').addEventListener('submit',e=>{submitting=e.target.id;setTimeout(()=>{submitting='';},0);},true);window.addEventListener('navigator:timeline-changed',()=>{if(submitting)dirtyForms.delete(submitting);unrecorded=dirtyForms.size>0;status();});setInterval(status,2000);status();
})();